func TestLocalSiteOverlap(t *testing.T) {
	t.Parallel()

	// to stop (*localSite).periodicFunctions()
	ctx, ctxCancel := context.WithCancel(context.Background())
	ctxCancel()

	srv := &server{
		ctx:             ctx,
		localAuthClient: &mockLocalSiteClient{},
	}
	srv.LocalAccessPoint = srv.localAuthClient

	site, err := newlocalSite(srv, "clustername", nil /* authServers */)
	require.NoError(t, err)
	require.Same(t, srv.LocalAccessPoint, site.accessPoint)
	require.Same(t, srv.localAuthClient, site.client)

	nodeID := uuid.NewString()
	connType := types.NodeTunnel
	dreq := &sshutils.DialReq{
		ServerID: nodeID,
		ConnType: connType,
	}

	conn1, err := site.addConn(nodeID, connType, mockRemoteConnConn{}, nil)
	require.NoError(t, err)

	conn2, err := site.addConn(nodeID, connType, mockRemoteConnConn{}, nil)
	require.NoError(t, err)

	c, err := site.getRemoteConn(dreq)
	require.True(t, trace.IsNotFound(err))
	require.Nil(t, c)

	conn1.setLastHeartbeat(time.Now())
	c, err = site.getRemoteConn(dreq)
	require.NoError(t, err)
	require.Equal(t, conn1, c)

	conn2.setLastHeartbeat(time.Now())
	c, err = site.getRemoteConn(dreq)
	require.NoError(t, err)
	require.Equal(t, conn2, c)

	conn2.markInvalid(nil)
	c, err = site.getRemoteConn(dreq)
	require.NoError(t, err)
	require.Equal(t, conn1, c)

	conn1.markInvalid(nil)
	c, err = site.getRemoteConn(dreq)
	require.True(t, trace.IsNotFound(err))
	require.Nil(t, c)
}

func TestRequireLocalAgentForConn(t *testing.T) {
	srv := &server{localSite: &localSite{domainName: "local"}}

	require.NoError(t, srv.requireLocalAgentForConn("local", types.NodeTunnel))

	err := srv.requireLocalAgentForConn("", types.NodeTunnel)
	require.True(t, trace.IsBadParameter(err))

	err = srv.requireLocalAgentForConn("remote", types.NodeTunnel)
	require.True(t, trace.IsBadParameter(err))
	require.ErrorContains(t, err, "remote")
	require.ErrorContains(t, err, string(types.NodeTunnel))
}

